import { cn } from '@/lib/cn'

type SkeletonProps = JSX.IntrinsicElements['div']

export function Skeleton(props: SkeletonProps) {
  const { class: className, ...rest } = props
  return (
    <div
      aria-hidden='true'
      data-slot='skeleton'
      class={cn('animate-pulse rounded-md bg-muted', className)}
      {...rest}
    />
  )
}
